contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address burner, uint256 initialBalance, uint256 burnAmount) public payable {
        require(initialBalance >= burnAmount);
        // Set up burner's balance by minting tokens as owner
        // But we cannot call mintToken here because it's onlyOwner.
        // Instead, we'll rely on the initial state from deployment; but we need a generic precondition.
        // Since we cannot change state as non-owner, we assume the c contract already has some state set up.
        // The test will use the given parameters and check the invariant after burn.
        // We need to call burn as the owner, but run() is not called by owner. So we need a different approach.
        // Actually, the difference is observable without being owner if we can observe balances.
        // We can call burn only if we are owner, but the test is not. So we must be the owner.
        // To be owner, we need the test contract to be the owner. We can set that up by having the constructor of the test contract receive the c instance that is already owned by the test contract itself? No, we cannot change ownership.
        // But the mutant changes burn behavior. We need to call burn as owner. Since the test contract is not the owner, we cannot call burn directly.
        // However, the difference is in how burn affects balanceOf and totalSupply. We can observe it if someone else burns, but we need to be the burner whose balance is affected.
        // The counterexample uses a specific call sequence: burn(...). So the test must call burn as the owner.
        // The test contract can be made the owner if we deploy C with the test contract as the constructor argument? But the test contract receives an already deployed C.
        // The instruction says: constructor(C _c) { c = _c; } and we interact only through c.
        // The test function is public, and we can call burn if msg.sender is owner. To make the test contract the owner, we need c.owner() to return address(this). But we cannot change ownership.
        // So we need a precondition that the test contract is the owner. We can require(c.owner() == address(this)).
        // Then we can call c.burn(burnAmount) as the burner, and our balanceOf will change.
        // Then assert about balanceOf[address(this)] and totalSupply.
        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();
        require(c.owner() == address(this));
        c.burn(burnAmount);
        uint256 balAfter = c.balanceOf(address(this));
        uint256 supplyAfter = c.totalSupply();
        assert(balAfter + supplyAfter == balBefore + supplyBefore - burnAmount);
    }
    receive() external payable {}
}

