pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(1000, "Test", "TST");
    }

    function testFuzz_property(uint256 burnAmount) public {
        burnAmount = bound(burnAmount, 1, 1000);
        address burner = address(0x1234);
        vm.prank(burner);
        c.transfer(burner, burnAmount);
        uint256 totalBefore = c.totalSupply();
        vm.prank(burner);
        c.burn(burnAmount);
        uint256 totalAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(burner);

        // For the correct contract, totalSupply reduction == burned amount and balanceOf reduced.
        // After burn, totalSupply must equal balanceOf(burner) + initialSupply minted to owner (1000 - burnAmount).
        // Actually, owner had 1000 initially, transferred burnAmount to burner, then burner burned.
        // After transfer: owner = 1000 - burnAmount, burner = burnAmount. After burn: burner balance = 0 (correct) or burnAmount (bug).
        // totalSupply after = 1000 - burnAmount. So totalSupply should equal owner balance + burner balance.
        uint256 ownerBalance = c.balanceOf(c.owner());
        assertTrue(totalAfter == ownerBalance + balanceAfter);
    }
}

