import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 amount, address burner) public {
        // Restrict amount to a reasonable range that will not overflow
        vm.assume(amount > 0 && amount <= 1e36);
        vm.assume(burner != address(0) && burner != address(c));

        // Set up owner and mint tokens to burner
        address originalOwner = address(this);
        c.mintToken(burner, amount);

        // Record balance before burn
        uint256 balanceBefore = c.balanceOf(burner);
        uint256 totalSupplyBefore = c.totalSupply();

        // Transfer ownership to burner so they can burn
        c.transferOwnership(burner);

        // Burn from burner's account
        vm.prank(burner);
        c.burn(amount);

        // After burn, sum of individual balances should equal totalSupply
        // We check only burner's balance since it's the only relevant account
        uint256 burnerBalanceAfter = c.balanceOf(burner);
        uint256 totalSupplyAfter = c.totalSupply();

        // In the correct contract: burner balance = balanceBefore - amount
        // totalSupply = totalSupplyBefore - amount, so they are consistent.
        // In the buggy contract: burner balance increases while totalSupply decreases,
        // causing totalSupply to be less than the sum of balances (since burner's balance > totalSupply).
        // The invariant: totalSupplyAfter must be at least the burner's balance (since only burner has tokens).
        assertTrue(totalSupplyAfter == burnerBalanceAfter);
    }
}

