    constructor(C _c) { c = _c; }
    function run(uint256 burnAmount) public payable {
        require(burnAmount > 0);
        require(c.balanceOf(address(this)) >= burnAmount);
        bool reverted;
        try c.burn(burnAmount) { reverted = false; } catch { reverted = true; }
        assert(!reverted ? c.totalSupply() < c.totalSupply() + 1 : true);
    }
}

contract InvMutTest {
