contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    function test(address burner, uint256 amount) public returns (bool) {
        require(burner != address(0));
        require(amount > 0);

        // Ensure burner has enough tokens by minting from the owner
        c.transfer(burner, amount);

        bool success;
        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(burner);
        (success, ) = address(c).call(abi.encodeWithSignature("burn(address,uint256)", burner, amount));

        uint256 supplyAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(burner);

        assert(supplyAfter == supplyBefore - amount && balanceAfter == balanceBefore - amount);
    }
