pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 mintAmount, uint256 burnAmount) public {
        vm.assume(caller != address(0));
        vm.assume(mintAmount > 0);
        vm.assume(burnAmount <= mintAmount);

        // owner mints tokens to caller
        vm.prank(c.owner());
        c.mintToken(caller, mintAmount);

        // caller attempts to burn tokens
        vm.prank(caller);
        c.burn(burnAmount);

        uint256 callerBalance = c.balanceOf(caller);
        uint256 totalSupply = c.totalSupply();
        // In the reference, onlyOwner restriction prevents non-owner burn, so balance remains mintAmount.
        // In buggy version, burn succeeds, reducing balance and totalSupply, but the invariant
        // that caller's balance must not exceed totalSupply should always hold.
        // However, if burnAmount > mintAmount, require would revert; the fuzzer explores valid ranges.
        // The crucial check: after a non-owner burn, the caller's balance must be <= totalSupply.
        // Reference: balance = mintAmount, totalSupply = mintAmount -> equality holds.
        // Buggy: balance = mintAmount - burnAmount, totalSupply = mintAmount - burnAmount -> equality holds.
        // Actually the difference appears if burnAmount is greater than mintAmount: reference reverts, buggy reverts (require balanceOf[msg.sender] >= _value).
        // Wait, the difference from the change: in reference, non-owner cannot burn at all (onlyOwner modifier).
        // So reference: non-owner burn reverts; buggy: non-owner burn succeeds if they have balance.
        // The property: For a non-owner, after a burn call, if it did not revert, their balance decreases by burnAmount.
        // We can capture revert behavior with try/catch.
        bool okRef;
        try c.burn(burnAmount) { okRef = true; } catch { okRef = false; }
        // But we already called burn above; to test revert difference, we need to check before/after state.
        // Instead, we can assert on the actual balance change relative to totalSupply.
        // Let's think: In reference, non-owner burn always reverts -> state unchanged.
        // In buggy, non-owner burn succeeds if sufficient balance -> state changes.
        // So after calling burn, if it succeeds, the caller's balance + burned amount should equal old balance.
        // But we need a universal property that holds in reference for ALL inputs.
        // Property: after a non-owner burn call (regardless of revert), the caller's balance remains unchanged from before the call.
        // That holds in reference because onlyOwner revert prevents execution.
        // In buggy, it changes, so violation.
        // We must test this without hardcoding.
        // We can snapshot balance before burn, then compare.
        uint256 balanceBefore = c.balanceOf(caller);
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));
        uint256 balanceAfter = c.balanceOf(caller);
        assertTrue(success ? balanceAfter == balanceBefore - burnAmount : balanceAfter == balanceBefore);
        // But this is not a general rule; it's scenario-specific.
        // General rule: For any non-owner, a burn call must not change totalSupply.
        // Reference: non-owner burn reverts, totalSupply unchanged.
        // Buggy: non-owner burn succeeds, totalSupply decreases.
        // So: after a burn call by non-owner, totalSupply must equal its previous value.
        uint256 tsBefore = c.totalSupply();
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));
        uint256 tsAfter = c.totalSupply();
        assertTrue(tsAfter == tsBefore);
    }
}
